"""Build the Doom firmware (doom.elf) for the "doom" address map with LLVM; no model is loaded.

  python chipformer/rv/env/doom/build.py     (from experimental/riscv)

Doom itself is smunaut/doom_riscv (id Software's GPL release, adapted for small RV32 machines),
fetched at a pinned commit and patched with doom.patch; qdoom.c, qlibc.c and start.S are the
platform. Set QDOOM_SRC to a patched source directory to build that instead.
"""

import os
import shutil
import subprocess
import sys
import tempfile
from pathlib import Path

os.environ.setdefault("QWENPUTER_RV_MAP", "doom")
HERE = Path(__file__).resolve().parent
sys.path[:0] = [str(HERE), str(HERE.parents[3])]

import wad

from chipformer.rv import spec as S

REPO = "https://github.com/smunaut/doom_riscv"
COMMIT = "02b0d8024ca66c713763a56e2230aecdbeae0961"
ZONE_KB = int(os.environ.get("QDOOM_ZONE_KB", "576"))
STACK = 64 * 1024
SOURCES = ["am_map", "d_items", "d_main", "d_net", "doomdef", "doomstat", "dstrings", "f_finale", "f_wipe", "g_game", "hu_lib", "hu_stuff", "info", "m_argv", "m_bbox", "m_cheat", "m_fixed", "m_menu", "m_misc", "m_random", "m_swap", "p_ceilng", "p_doors", "p_enemy", "p_floor", "p_inter", "p_lights", "p_map", "p_maputl", "p_mobj", "p_plats", "p_pspr", "p_saveg", "p_setup", "p_sight", "p_spec", "p_switch", "p_telept", "p_tick", "p_user", "r_bsp", "r_data", "r_draw", "r_main", "r_plane", "r_segs", "r_sky", "r_things", "sounds", "st_lib", "st_stuff", "tables", "v_video", "wi_stuff", "w_wad", "z_zone"]


def toolchain() -> tuple[str, list[str]]:
    clang = os.environ.get("RISCV_CLANG") or shutil.which("clang")
    if Path("/nix/store").exists() and "RISCV_CLANG" not in os.environ:
        found = sorted(p for p in Path("/nix/store").glob("*-clang-*/bin/clang")
                       if "wrapper" not in str(p))
        if found:
            clang = str(found[-1])
    linker = os.environ.get("RISCV_LLD") or shutil.which("ld.lld")
    if not linker and shutil.which("rustc"):
        root = Path(subprocess.check_output(["rustc", "--print", "sysroot"], text=True).strip())
        found = list(root.glob("lib/rustlib/*/bin/rust-lld"))
        if found:
            linker = str(found[0])
    if not clang or not linker:
        raise SystemExit("Set RISCV_CLANG and RISCV_LLD to LLVM clang and an ELF-capable lld.")
    return clang, [linker, "-flavor", "gnu"] if Path(linker).name == "rust-lld" else [linker]


def source() -> Path:
    if os.environ.get("QDOOM_SRC"):
        return Path(os.environ["QDOOM_SRC"])
    tree = wad.CACHE / f"doom_riscv-{COMMIT[:12]}"
    if not tree.is_dir():
        wad.CACHE.mkdir(parents=True, exist_ok=True)
        tmp = Path(tempfile.mkdtemp(prefix="doom_riscv-", dir=wad.CACHE))
        subprocess.run(["git", "init", "-q", str(tmp)], check=True)
        subprocess.run(["git", "-C", str(tmp), "fetch", "-q", "--depth", "1", REPO, COMMIT],
                       check=True)
        subprocess.run(["git", "-C", str(tmp), "checkout", "-q", "FETCH_HEAD"], check=True)
        subprocess.run(["git", "-C", str(tmp), "apply", str(HERE / "doom.patch")], check=True)
        tmp.rename(tree)
    return tree / "src"


def linker_script() -> str:
    ram_top = S.RAM_BASE + 4 * S.RAM_WORDS
    return f"""/* Generated by env/doom/build.py from spec.py's "doom" address map. */
ENTRY(_start)
MEMORY
{{
  RAM (rw) : ORIGIN = {S.RAM_BASE + S.DATA_BASE:#x}, LENGTH = {4 * S.RAM_WORDS - S.DATA_BASE:#x}
  DROM (r) : ORIGIN = {S.DROM_BASE:#x}, LENGTH = {4 * S.DROM_WORDS:#x}
  ROM (rx) : ORIGIN = {S.ROM_BASE:#x}, LENGTH = {4 * S.ROM_WORDS:#x}
}}
SECTIONS
{{
  .text : {{ *(.text.init) *(.text .text.*) }} > ROM
  .rodata : {{
    *(.rodata .rodata.* .srodata .srodata.*)
    *(.init_array .init_array.* .fini_array .fini_array.* .eh_frame .eh_frame_hdr)
  }} > DROM
  .data : {{ *(.data .data.* .sdata .sdata.*) }} > RAM
  .tdata : {{ __tls_base = .; *(.tdata .tdata.*) }} > RAM
  .tbss : {{ *(.tbss .tbss.*) }} > RAM
  .bss : {{
    . = . + SIZEOF(.tbss);
    *(.bss .bss.* .sbss .sbss.*) *(COMMON)
    . = ALIGN(16);
    __heap_start = .;
  }} > RAM
  __heap_end = {ram_top - STACK:#x};
  ASSERT(__heap_start <= __heap_end, "Doom's data does not fit the RAM")
}}
"""


def build(out: Path = HERE / "doom.elf") -> Path:
    assert S.MAP == "doom", "build with QWENPUTER_RV_MAP=doom"
    clang, lld = toolchain()
    src = source()
    flags = ["--target=riscv32-unknown-none-elf", "-march=rv32im", "-mabi=ilp32",
             "-msmall-data-limit=0", "-mno-relax", "-O2", "-ffreestanding", "-nostdlibinc",
             "-fno-stack-protector", "-fno-common", "-w", "-I", str(HERE / "include"),
             "-I", str(src), "-DNORMALUNIX", f"-DTEXT_ADDR={S.TEXT_ADDR:#x}",
             f"-DZONE_KB={ZONE_KB}"]
    with tempfile.TemporaryDirectory(prefix="qdoom-") as tmp:
        tmp = Path(tmp)
        wad.build(tmp / "doom1.wad")
        (tmp / "doom.ld").write_text(linker_script())
        units = [src / f"{n}.c" for n in SOURCES] + [HERE / f for f in
                 ("qdoom.c", "qlibc.c", "i_sound.c", "s_sound.c", "i_net.c", "start.S", "wad.S")]
        objs = []
        for unit in units:
            obj = tmp / (unit.name + ".o")
            subprocess.run([clang, *flags, f'-DWAD_PATH="{tmp / "doom1.wad"}"', "-c", str(unit),
                            "-o", str(obj)], check=True)
            objs.append(str(obj))
        subprocess.run([*lld, "-m", "elf32lriscv", "--no-relax", "--gc-sections", "-T",
                        str(tmp / "doom.ld"), *objs, "-o", str(out)], check=True)
    return out


if __name__ == "__main__":
    print(build())
